/* Новые звуки (Stable Audio 3, модель sm-sfx): сэмплы и привязка к событиям sun:*.
   Игровую логику не трогает. Таблицу сэмплов между маркерами переписывает
   tools/generate_sa3_sfx.py — не редактируйте её вручную.
   Сэмплы декодирует SFX.loadSamples() (js/audio.js) вместе с SFX_SAMPLES. */
/* @@SA3-SAMPLES-BEGIN (генерирует tools/generate_sa3_sfx.py) */
window.SFX_SA3_SAMPLES = {
  spawnLine: '',
  spawnSun: '',
  spawnBomb: '',
  spawnTotem: '',
  blastBomb: '',
  blastTotem: '',
  combo4: '',
  combo6: '',
  combo8: '',
  goGong: '',
  victory: '',
  defeat: '',
  shuffle: '',
  uiClick: '',
  hintChime: '',
};
/* @@SA3-SAMPLES-END */
(function () {
  "use strict";
  var SFX = window.SFX;
  if (!SFX) return;

  /* Все звуки идут через SFX.playSample: mute, громкость и шины — как у старых.
     Возвращает false, если сэмпла нет (тогда звучит старый вариант). */
  function play(name, opts) {
    try {
      var o = { rate: 0.97 + Math.random() * 0.06, wet: 0.06 };
      for (var k in opts) o[k] = opts[k];
      return SFX.playSample(name, o);
    } catch (e) {
      return false;
    }
  }
  var defer = window.queueMicrotask
    ? function (fn) { window.queueMicrotask(fn); }
    : function (fn) { Promise.resolve().then(fn); };

  /* Появление спецкамня. game.js вызывает SFX.special() и сразу же, синхронно,
     шлёт sun:special {type}. Поэтому общий звук откладываем на микрозадачу:
     если следом пришло событие — играем звук по типу вместо общего, если нет
     (перемешивание поля) — звучит прежний SFX.special(). */
  var SPAWN = { line: "spawnLine", sun: "spawnSun", bomb: "spawnBomb", totem: "spawnTotem" };
  var origSpecial = SFX.special;
  var specialPending = false;
  SFX.special = function () {
    var self = this;
    var args = arguments;
    specialPending = true;
    defer(function () {
      if (!specialPending) return;
      specialPending = false;
      origSpecial.apply(self, args);
    });
  };
  window.addEventListener("sun:special", function (e) {
    var name = SPAWN[e.detail && e.detail.type];
    specialPending = false;
    if (SFX.muted) return;
    if (name && play(name, { gain: 0.9, wet: 0.08 })) return;
    origSpecial.call(SFX);
  });

  /* Взрывы: бомбу озвучивает SFX.blast({bomb}) в audio.js (game.js передаёт
     счётчик). Тотем game.js считает «линией», так что lineBlast уже звучит —
     добавляем поверх резонансный удар тотема, один раз на волну. */
  var lastTotem = 0;
  window.addEventListener("sun:blast", function (e) {
    if (!e.detail || e.detail.type !== "totem") return;
    var t = Date.now();
    if (t - lastTotem < 80) return;
    lastTotem = t;
    play("blastTotem", { gain: 0.8, delay: 0.02 });
  });

  /* Стингеры комбо ×4/×6/×8: один раз на смену множителя, чуть позже и тише
     звука совпадения, чтобы лечь слоем поверх. */
  var STING = { 4: "combo4", 6: "combo6", 8: "combo8" };
  var lastMult = 1;
  window.addEventListener("sun:match", function (e) {
    var mult = e.detail ? Number(e.detail.mult) : 1;
    if (mult === lastMult) return;
    lastMult = mult;
    if (STING[mult]) play(STING[mult], { gain: 0.6, delay: 0.06 });
  });

  /* «ВПЕРЁД!» в отсчёте — гонг; «Камни перемешаны» в тосте — шорох камней.
     Прямых хуков в game.js нет, поэтому смотрим на текст элементов. */
  function watchText(id, onText) {
    var el = document.getElementById(id);
    if (!el || !window.MutationObserver) return;
    new MutationObserver(function () {
      onText((el.textContent || "").trim());
    }).observe(el, { childList: true, characterData: true, subtree: true });
  }
  function hookDom() {
    watchText("countdownNum", function (text) {
      if (text === "ВПЕРЁД!") play("goGong", { gain: 0.85 });
    });
    watchText("toast", function (text) {
      if (/^Камни перемешаны|перемешиваем/.test(text)) play("shuffle", { gain: 0.8 });
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", hookDom);
  else hookDom();
})();
